input.command:
mkdir -p src/main/java/com/example/app src/main/resources src/test/java/com/example/app src/test/resources && cat > src/main/java/com/example/app/App.java <<'EOF'
package com.example.app;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class App {

    private static final Logger log = LoggerFactory.getLogger(App.class);

    public static void main(String[] args) {
        log.info("Application starting with {} argument(s)", args.length);
        System.out.println(greet(args.length > 0 ? args[0] : "world"));
        log.info("Application finished");
    }

    static String greet(String name) {
        log.debug("Building greeting for name={}", name);
        return "Hello, " + name + "!";
    }
}
EOF
cat > src/test/java/com/example/app/AppTest.java <<'EOF'
package com.example.app;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.Test;

class AppTest {

    @Test
    void greetsByName() {
        assertEquals("Hello, Maven!", App.greet("Maven"));
    }
}
EOF
cat > src/main/resources/logback.xml <<'EOF'
<configuration>
    <appender name="CONSOLE" class="ch.qos.logback.core.ConsoleAppender">
        <encoder>
            <pattern>%d{HH:mm:ss.SSS} %-5level [%thread] %logger{36} - %msg%n</pattern>
        </encoder>
    </appender>

    <logger name="com.example" level="DEBUG"/>

    <root level="INFO">
        <appender-ref ref="CONSOLE"/>
    </root>
</configuration>
EOF
cat > src/test/resources/logback-test.xml <<'EOF'
<configuration>
    <appender name="CONSOLE" class="ch.qos.logback.core.ConsoleAppender">
        <encoder>
            <pattern>%-5level %logger{36} - %msg%n</pattern>
        </encoder>
    </appender>

    <root level="WARN">
        <appender-ref ref="CONSOLE"/>
    </root>
</configuration>
EOF
cat > .gitignore <<'EOF'
target/
*.class
.idea/
*.iml
.vscode/
.classpath
.project
.settings/
EOF
mvn -q -B verify 2>&1 | tail -20; echo EXIT ${PIPESTATUS[0]}
CP=$(mvn -q -B dependency:build-classpath -Dmdep.outputFile=/dev/stdout); java -cp "target/classes:$CP" com.example.app.App Claude

